import test from 'node:test';
import assert from 'node:assert/strict';
import { statement } from '../src/statements.js';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('statement returns customer statement', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  const result = statement('C-001', [issued.value], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, 'INV-2026-0001');
});

test('statement reports CUSTOMER_NOT_FOUND for unknown customer', () => {
  assert.deepEqual(statement('C-999', [], '2026-10-07'), { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('statement includes issued invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  const result = statement('C-001', [issued.value], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
});

test('statement excludes draft invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const result = statement('C-001', [r.value], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
});

test('statement excludes invoices with issueDate after asOf', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  const result = statement('C-001', [issued.value], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
});

test('statement includes invoices with issueDate equal to asOf', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  const result = statement('C-001', [issued.value], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
});

test('statement excludes other customers invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued1 = issueInvoice(r1.value, []);
  const issued2 = issueInvoice(r2.value, ['INV-2026-0001']);
  const result = statement('C-001', [issued1.value, issued2.value], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, 'INV-2026-0001');
});

test('statement sorts invoices by issueDate', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued1 = issueInvoice(r1.value, []);
  const issued2 = issueInvoice(r2.value, ['INV-2026-0001']);
  const result = statement('C-001', [issued1.value, issued2.value], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 2);
  assert.equal(result.value.invoices[0].issueDate, '2026-10-07');
  assert.equal(result.value.invoices[1].issueDate, '2026-10-15');
});

test('statement includes due amount for each invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  const result = statement('C-001', [issued.value], '2026-10-07');
  assert.equal(result.ok, true);
  assert.ok('due' in result.value.invoices[0]);
  assert.ok(result.value.invoices[0].due > 0);
});

test('statement calculates totalDue as sum of due amounts', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued1 = issueInvoice(r1.value, []);
  const issued2 = issueInvoice(r2.value, ['INV-2026-0001']);
  const result = statement('C-001', [issued1.value, issued2.value], '2026-10-31');
  const expectedTotal = result.value.invoices.reduce((sum, inv) => sum + inv.due, 0);
  assert.equal(result.value.totalDue, expectedTotal);
});

test('statement with partially_paid invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  const withPayment = recordPayment(issued.value, { amount: 5000, date: '2026-10-08' });
  const result = statement('C-001', [withPayment.value], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.ok(result.value.invoices[0].due < result.value.invoices[0].total);
});

test('statement excludes paid invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  const totals = invoiceTotals(issued.value);
  const paid = recordPayment(issued.value, { amount: totals.total, date: '2026-10-08' });
  const result = statement('C-001', [paid.value], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
});

test('statement normalizes customer ID', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  const result = statement('c-001', [issued.value], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
});

test('statement includes invoice details', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  const result = statement('C-001', [issued.value], '2026-10-07');
  const inv = result.value.invoices[0];
  assert.ok('number' in inv);
  assert.ok('issueDate' in inv);
  assert.ok('dueDate' in inv);
  assert.ok('total' in inv);
  assert.ok('due' in inv);
});

test('statement with empty invoices array', () => {
  const result = statement('C-001', [], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
  assert.equal(result.value.totalDue, 0);
});

test('statement totalDue is 0 when no invoices', () => {
  const result = statement('C-001', [], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.totalDue, 0);
});

test('statement with multiple customers', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  const r3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued1 = issueInvoice(r1.value, []);
  const issued2 = issueInvoice(r2.value, ['INV-2026-0001']);
  const issued3 = issueInvoice(r3.value, ['INV-2026-0002']);
  const result = statement('C-001', [issued1.value, issued2.value, issued3.value], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 2);
  assert.equal(result.value.invoices[0].issueDate, '2026-10-07');
  assert.equal(result.value.invoices[1].issueDate, '2026-10-15');
});

test('statement includes total from invoiceTotals', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  const totals = invoiceTotals(issued.value);
  const result = statement('C-001', [issued.value], '2026-10-07');
  assert.equal(result.value.invoices[0].total, totals.total);
});

test('statement filters correctly with mixed statuses', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
