    customerId: 'C-001',
    issueDate: '2026-10-20',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  const issued1 = issueInvoice(r1.value, []);
  const issued2 = issueInvoice(r2.value, ['INV-2026-0001']);
  const issued3 = issueInvoice(r3.value, ['INV-2026-0002']);
  const withPayment = recordPayment(issued3.value, { amount: 5000, date: '2026-10-21' });
  const result = statement('C-001', [issued1.value, issued2.value, withPayment.value], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 3);
});

test('statement due equals balance when no payments', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
