  const result = statement('C-001', [issued.value], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.ok(result.value.invoices[0].total > 0);
});

test('statement with discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  });
  const issued = issueInvoice(r.value, []);
  const result = statement('C-001', [issued.value], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
});

test('statement respects date boundaries', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-06',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued1 = issueInvoice(r1.value, []);
  const issued2 = issueInvoice(r2.value, ['INV-2026-0001']);
  const issued3 = issueInvoice(r3.value, ['INV-2026-0002']);
  const result = statement('C-001', [issued1.value, issued2.value, issued3.value], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 2);
  assert.equal(result.value.invoices[0].issueDate, '2026-10-06');
  assert.equal(result.value.invoices[1].issueDate, '2026-10-07');
});

